import json, random, subprocess, sys, copy

def tmpl_info(top, t):
    if top[0]=='leaf-spine':
        l=top[1]; i=t//(l-1); j=t%(l-1); 
        if j>=i:j+=1
        return i,[i,j]
    raise Exception()

def grp_stats(tasks, quotas,budgets,caps,n,templates):
    gl=[0]*len(quotas); gp=[set() for _ in quotas]; gc=[0]*len(quotas); gpin=[0]*len(quotas)
    pairs=[set() for _ in quotas]
    for task in tasks:
        t,g,w,c,p=task
        d,fp=tmpl_info(top,t)
        gl[g]+=w; gp[g].update(fp); gc[g]+=1; gpin[g]+=p; pairs[g].add((d,c))
    usage=[0]*n
    for g in range(len(quotas)):
        if gc[g]:
            for node in gp[g]: usage[node]+=quotas[g]
    return gl,gp,gc,gpin,pairs,usage

def cert(tasks,quotas,budgets,caps,n,templates,query):
    gl,gp,gc,gpin,pairs,usage=grp_stats(tasks,quotas,budgets,caps,n,templates)
    groups=[]
    for g in query['groups']:
        if gc[g]:
            assert len(pairs[g])==1
            d,c=next(iter(pairs[g]))
        else:d=c=-1
        groups.append([g,gc[g],gl[g],quotas[g],budgets[g],len(gp[g]),d,c])
    nodes=[[x,usage[x],caps[x]] for x in query['nodes']]
    taskrows=[[i,*tasks[i]] for i in query['tasks']]
    return {'totals':[sum(1 for x in gc if x),sum(usage),sum(t[2] for t in tasks),sum(t[4] for t in tasks)],
            'groups':groups,'nodes':nodes,'tasks':taskrows}

def initial_ok(tasks,quotas,budgets,caps,n,templates):
    gl,gp,gc,gpin,pairs,usage=grp_stats(tasks,quotas,budgets,caps,n,templates)
    for g in range(len(quotas)):
        if gc[g]:
            if quotas[g]<=0: return False
            if len(pairs[g])!=1:return False
            if gl[g]>quotas[g]*budgets[g]:return False
    for i in range(n):
        if usage[i]>caps[i]:return False
    return True

def model(top,caps,groups,tasks,transactions,initial_query):
    l=top[1];n=l+top[2];templates=l*(l-1)
    quotas=[x[0] for x in groups];budgets=[x[1] for x in groups]
    tasks=[list(x) for x in tasks]
    rev=0
    assert initial_ok(tasks,quotas,budgets,caps,n,templates)
    out={'nodes':n,'templates':templates,'initial':cert(tasks,quotas,budgets,caps,n,templates,initial_query),'transactions':[]}
    for tx in transactions:
        q=tx['query']
        if tx['revision']!=rev:
            out['transactions'].append({'accepted':False,'revision':rev,'violations':None,'certificate':cert(tasks,quotas,budgets,caps,n,templates,q)})
            continue
        oldtasks=[x[:] for x in tasks]; oldq=quotas[:]; oldb=budgets[:]; oldcaps=caps[:]
        start_pinned=[t[4] for t in tasks]; start_groups=[t[1] for t in tasks]
        tup={}; qu={}; bu={}; ca={}
        for e in tx['edits']:
            op,i,v=e
            if op in ('move','weight','class','bind','pin'):
                if i not in tup:tup[i]=tasks[i][:]
                if op=='move':tup[i][1]=v
                elif op=='weight':tup[i][2]=v
                elif op=='class':tup[i][3]=v
                elif op=='bind':tup[i][0]=v
                else:tup[i][4]=v
            elif op=='quota':qu[i]=v
            elif op=='budget':bu[i]=v
            else:ca[i]=v
        quotafinal=quotas[:];budgetfinal=budgets[:];capsfinal=caps[:]
        for _ in range(1):
            pass
        for g,v in qu.items():quotafinal[g]=v
        for g,v in bu.items():budgetfinal[g]=v
        for nd,v in ca.items():capsfinal[nd]=v
        newtasks=tasks[:]
        for i,t in tup.items():newtasks[i]=t[:]
        gl,gp,gc,gpin,pairs,usage=grp_stats(newtasks,quotafinal,budgetfinal,capsfinal,n,templates)
        capv=sum(1 for i in range(n) if usage[i]>capsfinal[i])
        mixv=sum(1 for g in range(len(quotas)) if len(pairs[g])>1)
        workv=sum(1 for g in range(len(quotas)) if gc[g] and (quotafinal[g]==0 or gl[g]>quotafinal[g]*budgetfinal[g]))
        qchange={g for g,v in qu.items() if v!=quotas[g]}
        pinv=0
        for tid in range(len(tasks)):
            if not start_pinned[tid]:continue
            old=tasks[tid]; new=newtasks[tid]
            fields=(old[1]!=new[1] or old[0]!=new[0] or old[2]!=new[2] or old[3]!=new[3])
            if fields or start_groups[tid] in qchange:pinv+=1
        viol=[capv,mixv,workv,pinv]
        if all(x==0 for x in viol):
            tasks=newtasks;quotas=quotafinal;budgets=budgetfinal;caps=capsfinal;rev+=1
            out['transactions'].append({'accepted':True,'revision':rev,'violations':viol,'certificate':cert(tasks,quotas,budgets,caps,n,templates,q)})
        else:
            tasks=oldtasks;quotas=oldq;budgets=oldb;caps=oldcaps
            out['transactions'].append({'accepted':False,'revision':rev,'violations':viol,'certificate':cert(tasks,quotas,budgets,caps,n,templates,q)})
    return out

def gen(seed):
    rnd=random.Random(seed)
    l=rnd.randint(2,5); s=rnd.randint(1,4); n=l+s; m=l*(l-1)
    ng=rnd.randint(1,4)
    # generate legal initial: each group choose domain (source leaf), class, quota, budget, set tasks templates with same domain/class
    groups=[]; tasks=[]
    for g in range(ng):
        quota=rnd.randint(1,4); budget=rnd.randint(1,8)
        groups.append([quota,budget])
        if rnd.random()<0.3: continue
        d=rnd.randrange(l); cls=rnd.randint(0,3)
        # templates with source d: for each dst != d
        choices=[d*(l-1)+ (j if j<d else j-1) for j in range(l) if j!=d]
        for _ in range(rnd.randint(1,4)):
            tasks.append([rnd.choice(choices),g,rnd.randint(1,6),cls,rnd.randint(0,1)])
    # choose caps to make legal, occasionally add slack
    _,gp,_,_,_,usage_base=grp_stats(tasks,[x[0] for x in groups],[x[1] for x in groups],[0]*n,n,m)
    caps=[usage_base[i]+rnd.randint(0,3) for i in range(n)]
    if not initial_ok(tasks,[x[0] for x in groups],[x[1] for x in groups],caps,n,m):
        raise Exception('gen invalid')
    def query():
        return {'groups':[rnd.randrange(ng) for _ in range(rnd.randint(0,5))],
                'nodes':[rnd.randrange(n) for _ in range(rnd.randint(0,5))],
                'tasks':[rnd.randrange(len(tasks)) for _ in range(rnd.randint(0,min(5,len(tasks))))] if tasks else []}
    startq=query()
    txs=[]; rev=0
    for ti in range(rnd.randint(0,60)):
        if rnd.random()<0.2:
            r=rnd.choice([max(0,rev-1),rev+1,rnd.randint(0,5)])
        else:r=rev
        edits=[]
        for _ in range(rnd.randint(0,8)):
            op=rnd.choice(['move','weight','class','bind','pin','quota','budget','cap'])
            if op in ('move','weight','class','bind','pin'):
                if not tasks:continue
                i=rnd.randrange(len(tasks))
                if op=='move':v=rnd.randrange(ng)
                elif op=='weight':v=rnd.randint(1,9)
                elif op=='class':v=rnd.randint(0,4)
                elif op=='bind':v=rnd.randrange(m)
                else:v=rnd.randint(0,1)
            elif op in ('quota','budget'):
                i=rnd.randrange(ng);v=rnd.randint(0,4) if op=='quota' else rnd.randint(1,8)
            else:
                i=rnd.randrange(n);v=rnd.randint(0,10)
            edits.append([op,i,v])
        if rnd.random()<0.3: # duplicate assignments on same target/field
            pass
        txs.append({'revision':r,'edits':edits,'query':query()})
        # only increment rev via accepted; model handles actual; compute to choose future maybe approximate
        # We'll update rev by invoking model? Easier all future r random enough
    return {'topology':['leaf-spine',l,s],'caps':caps,'groups':groups,'tasks':tasks,'query':startq,'transactions':txs},l,n,m

def run_one(seed):
    sess,l,n,m=gen(seed)
    req={'version':2,'sessions':[sess]}
    exp={'sessions':[model(sess['topology'],sess['caps'],sess['groups'],sess['tasks'],sess['transactions'],sess['query'])]}
    p=subprocess.run(['python3','-B','/workspace/submission/main.py'],input=json.dumps(req,separators=(',',':')).encode(),stdout=subprocess.PIPE,stderr=subprocess.PIPE,cwd='/workspace')
    if p.returncode!=0:
        print('RET',seed,p.returncode,p.stderr.decode()[:1000]);return False
    try:got=json.loads(p.stdout)
    except Exception as e:
        print('JSON',seed,e,p.stdout[:500]);return False
    if got!=exp:
        print('MISMATCH seed',seed)
        # find first diff
        def diff(a,b,path=''):
            if type(a)!=type(b):print('type',path,a,b);return True
            if isinstance(a,dict):
                if a.keys()!=b.keys():print('keys',path,a.keys(),b.keys());return True
                for k in a:
                    if diff(a[k],b[k],path+'/'+str(k)):return True
            elif isinstance(a,list):
                if len(a)!=len(b):print('len',path,len(a),len(b));return True
                for i,(x,y) in enumerate(zip(a,b)):
                    if diff(x,y,path+'/'+str(i)):return True
            elif a!=b:print('val',path,a,b);return True
            return False
        diff(got,exp)
        open('/workspace/tmp/lastreq.json','w').write(json.dumps(req))
        open('/workspace/tmp/lastgot.json','w').write(json.dumps(got))
        open('/workspace/tmp/lastexp.json','w').write(json.dumps(exp))
        return False
    return True

for seed in range(300):
    if not run_one(seed):
        print('failed at',seed);sys.exit(1)
print('ALL OK')
